def frequencies_brute(a: list[int]) -> dict[int, int]:
    n = len(a)
    out: dict[int, int] = {}
    for i in range(n):
        if a[i] in out:
            continue
        cnt = 0
        for j in range(n):
            if a[j] == a[i]:
                cnt += 1
        out[a[i]] = cnt
    return out

from collections import Counter

def frequencies(a: list[int]) -> dict[int, int]:
    return dict(Counter(a))
